(118, '阿姆斯特丹運河騎行', 'amsterdam-guide-1-118', '<h2>阿姆斯特丹・運河騎行</h2>
<p>本篇帶你用一天的節奏認識阿姆斯特丹，主題聚焦「運河騎行」。文中穿插實地照片，方便對照路線與氛圍。圖片皆來自本站整理之城市圖庫。</p>
